      ['Name', 'Identifiers', 'Domain', 'Scope', 'SizeKb'].forEach(f => {
        const el = document.getElementById('sort-' + f);
        if (el) el.innerText = (f === field) ? (currentSortAsc ? '▲' : '▼') : '';
