        try {
            $fg = Invoke-RestMethod -Uri "http://127.0.0.1:$daemonPort/foreground" -Method Post -Body (@{ title = "LCM Control Hub" } | ConvertTo-Json) -ContentType "application/json" -TimeoutSec 1 -ErrorAction SilentlyContinue
